function initNavTabs(){const nav=document.querySelector('.nav');if(!nav)return;const saved=JSON.parse(localStorage.getItem(KEY+'_navOrder')||'null');if(Array.isArray(saved)){saved.forEach(id=>{const el=nav.querySelector('.nav-tab[data-tab="'+id+'"]');if(el)nav.appendChild(el)})}let dragTimer=null;let dragActive=false;let dragEl=null;let startX=0,startY=0;let suppressClick=false;const clearDrag=()=>{clearTimeout(dragTimer);dragTimer=null;document.querySelectorAll('.nav-tab').forEach(x=>x.classList.remove('dragging','drop-before','drop-after'));dragEl=null;dragActive=false};document.querySelectorAll('.nav-tab').forEach(el=>{el.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;startX=e.clientX;startY=e.clientY;dragEl=el;dragActive=false;suppressClick=false;clearTimeout(dragTimer);dragTimer=setTimeout(()=>{if(dragEl===el){dragActive=true;el.setPointerCapture?.(e.pointerId);el.classList.add('dragging')}},280)});el.addEventListener('pointermove',e=>{if(dragEl!==el)return;const dx=e.clientX-startX,dy=e.clientY-startY;if(!dragActive){if(Math.abs(dx)>10&&Math.abs(dx)>Math.abs(dy)){clearTimeout(dragTimer);dragEl=null;return}return}const target=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.nav-tab');document.querySelectorAll('.nav-tab').forEach(x=>x.classList.remove('drop-before','drop-after'));if(!target||target===el)return;const r=target.getBoundingClientRect();if(e.clientX<r.left+r.width/2){target.classList.add('drop-before');if(el!==target.previousElementSibling)nav.insertBefore(el,target)}else{target.classList.add('drop-after');if(el!==target.nextElementSibling)nav.insertBefore(el,target.nextElementSibling)}});el.addEventListener('pointerup',e=>{if(dragEl!==el)return;clearTimeout(dragTimer);if(dragActive){suppressClick=true;localStorage.setItem(KEY+'_navOrder',JSON.stringify([...document.querySelectorAll('.nav-tab')].map(x=>x.dataset.tab)));setTimeout(()=>suppressClick=false,100)}clearDrag()});el.addEventListener('pointercancel',clearDrag);el.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopPropagation();suppressClick=false}},true)});}
function perfSince(period){
  const h=Object.entries(db.perfHistory||{}).map(([date,v])=>({date,value:Number(v.value)||0})).filter(x=>x.value>0).sort((a,b)=>a.date.localeCompare(b.date));
  if(!h.length)return null; const now=new Date(), y=String(now.getFullYear()), m=y+'-'+String(now.getMonth()+1).padStart(2,'0');
  let base=h[0]; if(period==='month'){base=h.filter(x=>x.date.slice(0,7)===m)[0]||h[h.length-1]} if(period==='year'){base=h.filter(x=>x.date.slice(0,4)===y)[0]||h[h.length-1]}
  const cur=h[h.length-1].value; return base.value?((cur/base.value)-1)*100:null;
}
function setPerf(id,v){const e=$(id);if(!e)return;e.textContent=v==null?'—':(v>=0?'+':'')+v.toFixed(2)+'%';e.className='value '+(v==null?'':v<0?'perf-negative':'perf-positive')}
function ensurePerfHistory(total){if(!db.perfHistory||typeof db.perfHistory!=='object'||Array.isArray(db.perfHistory))db.perfHistory={};const value=Number(total)||0;if(value>0){const day=new Date().toISOString().slice(0,10);db.perfHistory[day]={value};localStorage.setItem(KEY,JSON.stringify(db));}}
// Reconstruye las posiciones a partir del historial de compras y ventas.
function holdings(){
  const groups=new Map();
  const moves=[...(Array.isArray(db.moves)?db.moves:[])].filter(m=>m&&m.ticker).sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
  for(const m of moves){
    const type=String(m.type||'').toLowerCase();
    if(!['compra','venta'].includes(type)) continue;
    const ticker=String(m.ticker).trim().toUpperCase();
    const cat=String(m.cat||'Otro');
    const broker=String(m.broker||'Sin broker').trim()||'Sin broker';
    const key=[ticker,cat,broker].join('|');
    let x=groups.get(key);
    if(!x){x={ticker,cat,broker,qty:0,cost:0};groups.set(key,x)}
    const qty=Math.abs(Number(m.qty)||0);
    const amount=Math.abs(Number(m.amount)||((Number(m.unit)||0)*qty));
    if(type==='compra'){
      x.qty+=qty;
      x.cost+=amount;
    }else if(qty>0&&x.qty>0){
      const sold=Math.min(qty,x.qty);
      const avg=x.cost/x.qty;
      x.qty-=sold;
      x.cost=Math.max(0,x.cost-avg*sold);
    }
  }
  return [...groups.values()].filter(x=>x.qty>1e-10).map(x=>({...x,price:Number(db.prices?.[x.ticker]?.ars)||0,value:x.qty*(Number(db.prices?.[x.ticker]?.ars)||0),result:x.qty*(Number(db.prices?.[x.ticker]?.ars)||0)-x.cost}));
}
function brokerPositions(){return holdings();}
