function brokerPeriodReturn(name,period){const a=db.brokerPerf?.[name]||[];if(a.length<2)return null;const now=new Date(),start=new Date(now);if(period==='month')start.setMonth(now.getMonth()-1);if(period==='year')start.setFullYear(now.getFullYear()-1);const eligible=a.filter(x=>new Date(x.date)<=now);const baseline=eligible.filter(x=>new Date(x.date)<=start).slice(-1)[0];const last=eligible[eligible.length-1];if(!baseline||!last||baseline.value<=0)return null;return (last.value/baseline.value-1)*100}
function renderBrokers(){brokerSnapshot();const ps=brokerPositions(),b={};ps.forEach(x=>{if(!b[x.broker])b[x.broker]={value:0,cost:0,tickers:[]};const p=Number(db.prices[x.ticker]?.ars)||0;b[x.broker].value+=x.qty*p;b[x.broker].cost+=x.cost;b[x.broker].tickers.push(x.ticker)});const all=Object.values(b),total=all.reduce((a,x)=>a+x.value,0),weightBase=total>0?total:all.reduce((a,x)=>a+x.cost,0);$('brokersTable').innerHTML=Object.entries(b).map(([k,v])=>{const weight=weightBase>0?(total>0?v.value:v.cost)/weightBase*100:0;return `<tr class="broker-row" onclick="showBroker('${esc(k)}')"><td><b>${esc(k)}</b></td><td>${v.value?money(v.value):'—'}</td><td>${weight.toFixed(1)}%</td><td>${[...new Set(v.tickers)].map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</td></tr>`}).join('')||'<tr><td colspan="4">Sin posiciones.</td></tr>'}
function showBroker(name){const hs=brokerPositions().filter(x=>x.broker===name);$('brokerDetail').classList.remove('hide');const total=hs.reduce((a,x)=>a+x.qty*(Number(db.prices[x.ticker]?.ars)||0),0),cost=hs.reduce((a,x)=>a+x.cost,0),res=total-cost,pct=cost&&total?(total/cost-1)*100:null,month=brokerPeriodReturn(name,'month'),year=brokerPeriodReturn(name,'year');$('brokerDetail').innerHTML=`<div class="section-head"><h3>${esc(name)}</h3><button onclick="$('brokerDetail').classList.add('hide')">Cerrar</button></div><div class="metric-grid"><div class="metric-card"><div class="label">Invertido</div><div class="num">${money(cost)}</div></div><div class="metric-card"><div class="label">Valuación actual</div><div class="num">${total?money(total):'—'}</div></div><div class="metric-card"><div class="label">Resultado</div><div class="num ${res<0?'loss':'gain'}">${total?money(res):'—'}</div></div><div class="metric-card"><div class="label">Rendimiento acumulado</div><div class="num ${pct!=null&&pct<0?'loss':'gain'}">${pct!=null?pct.toFixed(2)+'%':'—'}</div></div><div class="metric-card"><div class="label">Rendimiento último mes</div><div class="num ${month!=null&&month<0?'loss':'gain'}">${month!=null?month.toFixed(2)+'%':'Acumulando'}</div><div class="hint">Se calcula desde la primera valuación disponible del período.</div></div><div class="metric-card"><div class="label">Rendimiento último año</div><div class="num ${year!=null&&year<0?'loss':'gain'}">${year!=null?year.toFixed(2)+'%':'Acumulando'}</div><div class="hint">Se calcula desde la primera valuación disponible del período.</div></div></div><div class="notice small">La valuación y el resultado se actualizan con las cotizaciones disponibles. Los rendimientos mensual y anual se habilitan al contar con valuaciones históricas suficientes; mientras tanto figura “Acumulando”, sin inventar resultados.</div><table><tr><th>Ticker</th><th>Categoría</th><th>Cantidad</th><th>PPC</th><th>Cotización</th><th>Invertido</th><th>Resultado</th><th>Rendimiento</th></tr>${hs.map(x=>{const p=Number(db.prices[x.ticker]?.ars)||0,v=x.qty*p,r=v-x.cost,rp=x.cost&&v?(v/x.cost-1)*100:null;return `<tr><td>${esc(x.ticker)}</td><td>${esc(x.cat)}</td><td>${x.qty}</td><td>${money(x.qty?x.cost/x.qty:0)}</td><td>${p?money(p):'—'}</td><td>${v?money(v):'—'}</td><td class="${r<0?'loss':'gain'}">${p?money(r):'—'}</td><td class="${rp!=null&&rp<0?'loss':'gain'}">${rp!=null?rp.toFixed(2)+'%':'—'}</td></tr>`}).join('')}</table>`}
async function showInstrument(t){const x=holdings().find(a=>a.ticker===t);if(!x)return;$('instrument').classList.remove('hide');$('instrument').innerHTML='<div class="section-head"><h3>Ficha · '+esc(t)+'</h3><span class="pill">Conectando datos…</span></div>';try{await syncTicker(t)}catch(e){}try{await syncFX()}catch(e){}const p=db.prices[t]||{},meta=db.marketMeta?.[t]||{};const [localQ,u]=await Promise.all([fetchLocalQuote(t),fetchUSQuote(t)]),ratio=Number(db.ratios[t])||Number(localQ?.ratio)||Number(meta.ratio)||Number(commonRatios[t])||0,ccl=Number(db.fx?.ccl)||Number(localQ?.impliedCcl)||0;let local=Number(localQ?.ars)||Number(meta.price||p.ars)||0;const theoretical=Number(localQ?.theoretical)||((u?.usd&&ccl&&ratio)?u.usd*ccl/ratio:0);if(!local&&theoretical)local=theoretical;db.prices[t]={...(db.prices[t]||{}),ars:local,source:localQ?.source||meta.source||p.source||'',usd:u?.usd||p.usd||0,ratio,theoretical};localStorage.setItem(KEY,JSON.stringify(db));const rp=x.cost&&local?((x.qty*local-x.cost)/x.cost*100):0;const tv=tvSymbol(t),id=t.replace(/[^A-Za-z0-9_]/g,'_'),isCedear=x.cat==='CEDEAR';const logo=logoUrl(t);$('instrument').innerHTML=`<div class="section-head"><div class="asset-head"><img class="asset-logo" src="${logo}" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><span class="tag" style="display:none;width:42px;height:42px;border-radius:50%;align-items:center;justify-content:center;font-weight:800">${esc(t.slice(0,2))}</span><div><h3 style="margin:0">${esc(t)} · ${esc(meta.name||t)}</h3><div class="muted small">${esc(x.cat)} · ${esc(x.broker||'Sin broker')} · Cantidad ${x.qty}</div></div></div><button onclick="$('instrument').classList.add('hide')">Cerrar</button></div><div class="metric-grid" style="margin-top:12px"><div class="metric-card"><div class="label">PPC</div><div class="num">${money(x.qty?x.cost/x.qty:0)}</div><div class="hint">Precio promedio realmente pagado.</div></div><div class="metric-card"><div class="label">Precio actual ARS</div><div class="num">${local?money(local):'—'}</div><div class="hint">${esc(meta.source||'Fuente pública')}</div></div><div class="metric-card"><div class="label">Subyacente USD</div><div class="num">${u?.usd?usd(u.usd):'—'}</div><div class="hint">${u?'Cotización pública externa':'No disponible para este ticker.'}</div></div><div class="metric-card"><div class="label">Resultado</div><div class="num ${(x.qty*local-x.cost)<0?'loss':'gain'}">${local?money(x.qty*local-x.cost):'—'}</div><div class="hint">${local?rp.toFixed(2)+'% sobre la inversión':'Sin valuación actual'}</div></div></div><div class="metric-grid" style="margin-top:10px"><div class="metric-card"><div class="label">Ratio CEDEAR</div><div class="num">${isCedear?(ratio||'—'):'No aplica'}</div><div class="hint">Relación de CDR respecto del subyacente.</div></div><div class="metric-card"><div class="label">CCL</div><div class="num">${ccl?money(ccl):'—'}</div><div class="hint">Tipo de cambio usado para paridad.</div></div><div class="metric-card"><div class="label">Valor teórico CDR</div><div class="num">${isCedear&&theoretical?money(theoretical):'—'}</div><div class="hint">Subyacente × CCL ÷ ratio.</div></div><div class="metric-card"><div class="label">Desarbitraje</div><div class="num ${theoretical&&local>theoretical?'loss': 'gain'}">${isCedear&&theoretical?((local/theoretical-1)*100).toFixed(2)+'%':'—'}</div><div class="hint">Diferencia frente a la paridad teórica.</div></div></div><div class="card"><div class="section-head"><h3>📊 Análisis fundamental</h3><span class="pill">TradingView · datos del proveedor</span></div><div class="notice small">La ficha siguiente trae las métricas fundamentales que TradingView disponibiliza para ${esc(tv)}. No se inventan valores faltantes.</div><div id="fundamentalWidget_${id}" class="tvbox"></div></div><div class="card"><div class="section-head"><h3>🧭 Análisis técnico</h3><span class="pill">TradingView · 1D</span></div><div id="technicalWidget_${id}" class="tvbox"></div></div><div class="card"><div class="section-head"><h3>👥 Previsión y consenso de analistas</h3><button onclick="openAnalystForecast('${esc(t)}')">Abrir previsión</button></div><div class="analyst-layout"><div><div id="forecastVisual_${id}" class="forecast-visual"><div class="muted small" style="padding:14px">Consultando objetivos de analistas…</div></div><div class="forecast-legend"><span style="color:var(--r)">Máx.</span><span style="color:var(--g)">Promedio</span><span style="color:var(--b)">Mín.</span><span id="forecastCount_${id}">Analistas: —</span></div></div><div class="rating-gauge"><div class="gauge-ring"><div class="label">CONSENSO</div><div class="rating" id="analystRating_${id}">—</div><div class="muted small">TradingView / FactSet</div></div></div></div></div><div class="card"><div class="section-head"><h3>📈 Gráfico TradingView</h3><button onclick="loadInstrumentChart('${esc(t)}')">Recargar gráfico</button></div><div id="tvInstrument_${id}" class="tvbox tv-chart-large"></div></div><div class="card"><h3>Fair Value</h3><div class="notice small"><b>Fair Value = valor razonable estimado.</b> Es una estimación de valoración de la empresa/acción basada en un modelo o fuente concreta. No es el valor teórico del CEDEAR. Como no tenemos una fuente gratuita estable que entregue ese número para todos los activos, no voy a poner un número inventado. Cuando exista una fuente verificable, aparecerá con su fuente.</div></div>`;setTimeout(()=>{mountTVWidget('fundamentalWidget_'+id,'embed-widget-financials.js',{colorTheme:'dark',isTransparent:true,displayMode:'adaptive',width:'100%',height:'520',symbol:tv,locale:'es'});mountTVWidget('technicalWidget_'+id,'embed-widget-technical-analysis.js',{interval:'1D',width:'100%',height:'430',symbol:tv,showIntervalTabs:true,displayMode:'single',locale:'es',colorTheme:'dark',isTransparent:true});loadInstrumentChart(t);loadAnalystData(t,id)},100)}
async function loadAnalystData(t,id){const el=$('forecastVisual_'+id),rating=$('analystRating_'+id),count=$('forecastCount_'+id);if(!el)return;try{const sym=tvSymbol(t).replace(':','-');const url='https://r.jina.ai/https://www.tradingview.com/symbols/'+encodeURIComponent(sym)+'/forecast/';const r=await fetch(url);if(!r.ok)throw 0;const txt=await r.text();const maxm=txt.match(/max estimate of[^$\d]*[$€£]?([\d,.]+)/i),minm=txt.match(/min estimate of[^$\d]*[$€£]?([\d,.]+)/i),pt=txt.match(/Price target\s+([\d,.]+)/i),nm=txt.match(/(\d+) analysts[^\n]{0,100}(?:price forecasts|giving stock ratings)/i);const clean=v=>v?Number(String(v).replace(/,/g,'')):0;const hi=clean(maxm?.[1]),lo=clean(minm?.[1]),avg=clean(pt?.[1]);let n=nm?Number(nm[1]):0;if(!hi&&!lo){el.innerHTML='<div class="muted small" style="padding:14px">TradingView no publicó objetivos para este símbolo.</div>';return}const mx=Math.max(hi,avg,lo),mn=Math.min(hi,avg,lo),span=Math.max(1,mx-mn),y=v=>20+(mx-v)/span*175;el.innerHTML='<div style="position:absolute;left:8%;right:8%;top:18px;bottom:22px;border-left:1px solid var(--line);border-bottom:1px solid var(--line)"></div><div class="forecast-line" style="top:'+y(hi)+'px;background:var(--r)"></div><div class="forecast-line" style="top:'+y(avg)+'px;background:var(--g)"></div><div class="forecast-line" style="top:'+y(lo)+'px;background:var(--b)"></div><div class="forecast-label" style="right:2%;top:'+Math.max(5,y(hi)-8)+'px">Máx. '+usd(hi)+'</div><div class="forecast-label" style="right:2%;top:'+Math.max(5,y(avg)-8)+'px">Prom. '+usd(avg)+'</div><div class="forecast-label" style="right:2%;top:'+Math.max(5,y(lo)-8)+'px">Mín. '+usd(lo)+'</div><div class="muted small" style="position:absolute;left:10px;bottom:6px">Objetivos a 1 año · TradingView / FactSet</div>';count.textContent='Analistas: '+(n||'—');rating.textContent='Ver consenso';}catch(e){el.innerHTML='<div class="muted small" style="padding:14px">No se pudo traer la previsión automáticamente. Podés abrirla directamente en TradingView.</div>';rating.textContent='—';}}
