async function syncFX(){
  const urls=[
    ['DolarAPI CCL/MEP/oficial',async()=>{const [c,m,o]=await Promise.all([fetch('https://dolarapi.com/v1/dolares/contadoconliqui').then(r=>r.json()),fetch('https://dolarapi.com/v1/dolares/bolsa').then(r=>r.json()),fetch('https://dolarapi.com/v1/dolares/oficial').then(r=>r.json())]);return {ccl:+(c.venta||c.compra)||0,mep:+(m.venta||m.compra)||0,official:+(o.venta||o.compra)||0,date:c.fechaActualizacion||new Date().toISOString()}}],
    ['Dolarazo',async()=>{const d=await fetch('https://www.dolarazo.com.ar/api/v1/cotizaciones/dolares').then(r=>r.json());const a=Array.isArray(d.data)?d.data:d.data?.dolares||d.data||[];const find=k=>a.find(x=>String(x.casa||x.nombre||x.tipo||'').toLowerCase().includes(k));const c=find('contado')||find('liqui'),m=find('bolsa')||find('mep'),o=find('oficial');return {ccl:+(c?.venta||c?.sell||c?.precioVenta)||0,mep:+(m?.venta||m?.sell||m?.precioVenta)||0,official:+(o?.venta||o?.sell||o?.precioVenta)||0,date:new Date().toISOString()}}]
  ];
  for(const [,fn] of urls){try{const x=await fn();if(x.ccl||x.mep||x.official){db.fx=x;save();return x}}catch(e){}}
  throw new Error('No se pudo obtener dólar desde las fuentes gratuitas');
}
async function syncBYMA(){const base='https://open.bymadata.com.ar/vanoms-be-core/rest/api/bymadata/free',out={cedears:[],bonds:[],ons:[]};const post=async(path,body)=>{const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error(path+' '+r.status);return r.json()};try{const j=await post('/cedears',{T0:true,page_size:5000});out.cedears=Array.isArray(j)?j:(j.data||[])}catch(e){}try{const j=await post('/public-bonds',{T0:true,page_size:10000});out.bonds=j.data||[]}catch(e){}try{const j=await post('/negociable-obligations',{T0:true,page_size:10000});out.ons=Array.isArray(j)?j:(j.data||[])}catch(e){}db.marketMeta=db.marketMeta||{};const put=(a,kind)=>{for(const x of a||[]){const raw=String(x.symbol||x.ticker||'').trim();const t=raw.replace(/(?:C|D)$/,'');if(!t)continue;const px=Number(x.trade||x.closingPrice||x.settlementPrice)||0;if(px)db.prices[t]={...(db.prices[t]||{}),ars:px,source:'BYMA',updated:x.tradeHour||new Date().toISOString()};db.marketMeta[t]={...(db.marketMeta[t]||{}),symbol:raw,price:px,currency:x.denominationCcy||x.currency||'',maturity:x.maturityDate||'',days:x.daysToMaturity||0,source:'BYMA',change:x.previousClosingPrice&&px?((px/x.previousClosingPrice)-1)*100:Number(x.imbalance||0)*100,bid:Number(x.bidPrice||0),ask:Number(x.offerPrice||0),volume:Number(x.volume||0),kind}}};put(out.cedears,'CEDEAR');put(out.bonds,'Bono');put(out.ons,'ON');db.marketMeta._loadedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(db));return out}
