function makeHardDollarSchedule({maturity,amortStart,amortCount,amortPct,couponSteps}){const dates=makeSemiDates('2027-01-09',maturity);let residual=100;return {currency:'USD',maturity,coupon:couponSteps.map(x=>x[1]+'% desde '+x[0]).join(' · '),payments:dates.map(date=>{let rate=5;for(const step of couponSteps){if(date>=step[0])rate=step[1]}let interest=residual*rate/100/2;let amort=(date>=amortStart&&dates.indexOf(date)<dates.indexOf(amortStart)+amortCount)?Math.min(amortPct,residual):0;const row=[date,amort,interest];residual=Math.max(0,residual-amort);return row}).filter(p=>p[0]<=maturity)} }
