async function fetchYahooChart(symbol){
  const target='https://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(symbol)+'?range=1d&interval=1m';
  const urls=[target,'https://corsproxy.io/?url='+encodeURIComponent(target),'https://api.allorigins.win/raw?url='+encodeURIComponent(target),'https://r.jina.ai/http://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(symbol)+'?range=1d%26interval=1m'];
  for(const url of urls){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)continue;const j=await r.json().catch(()=>null);const m=j?.chart?.result?.[0]?.meta;const px=Number(m?.regularMarketPrice||m?.previousClose)||0;if(px)return {price:px,currency:m?.currency||'',source:'Yahoo Finance',symbol};}catch(e){}}
  return null;
}
function arNum(v){
  let z=String(v??'').replace(/u\$s|\$|%/gi,'').trim().replace(/\s/g,'');
  if(!z)return 0;
  if(z.includes(',')&&z.includes('.'))z=z.replace(/\./g,'').replace(',','.');
  else if(z.includes(','))z=z.replace(',','.');
  return Number(z)||0;
}
let cedearTableCache={at:0,text:''};
async function fetchCedearPublicData(t){
  t=String(t||'').toUpperCase().trim(); if(!t)return null;
  const page='https://www.sinelefantesblancos.com.ar/inversiones/CEDEAR';
  const urls=['https://r.jina.ai/https://www.sinelefantesblancos.com.ar/inversiones/CEDEAR','https://r.jina.ai/http://www.sinelefantesblancos.com.ar/inversiones/CEDEAR',page];
  let txt=(Date.now()-cedearTableCache.at<180000)?cedearTableCache.text:'';
  if(!txt){for(const url of urls){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)continue;txt=await r.text();if(txt&&txt.length>5000){cedearTableCache={at:Date.now(),text:txt};break}}catch(e){}}}
  if(!txt)return null;
  const lines=txt.split(/\r?\n/);
  for(const line of lines){
    const cols=line.split('|').map(x=>x.trim()).filter(Boolean);
    if(cols.length<10)continue;
    // Tabla: subyacente | nombre | mercado | USD | var | especie BYMA | ARS | var | ratio | CCL implícito | diferencia | teórico
    if(String(cols[0]).toUpperCase()===t && String(cols[5]).toUpperCase()===t){
      const usd=arNum(cols[3]), ars=arNum(cols[6]), ratio=arNum(cols[8]), impliedCcl=arNum(cols[9]), deviation=arNum(cols[10]), theoretical=arNum(cols[11]);
      if(ars||usd)return {ticker:t,usd,ars,ratio,impliedCcl,deviation,theoretical,source:'Tabla CEDEAR pública (Yahoo/BYMA)',updated:new Date().toISOString()};
    }
  }
  return null;
}
