async function syncPortfolio(){
  if($('connStatus'))$('connStatus').textContent='Actualizando cotizaciones…';
  try{await syncFX()}catch(e){}
  try{await syncBYMA()}catch(e){}
  const hs=holdings();
  for(const x of hs){
    if(!['CEDEAR','Acción','ETF'].includes(x.cat))continue;
    const prev=db.prices[x.ticker]||{};
    const [localQ,u]=await Promise.all([fetchLocalQuote(x.ticker),fetchUSQuote(x.ticker)]);
    const ratio=Number(db.ratios[x.ticker])||Number(localQ?.ratio)||Number(db.marketMeta?.[x.ticker]?.ratio)||Number(commonRatios[x.ticker])||0;
    const ccl=Number(db.fx?.ccl)||0;
    let ars=Number(localQ?.ars)||Number(db.marketMeta?.[x.ticker]?.price)||Number(prev.ars)||0;
    let arsSource=localQ?.source||(ars?db.marketMeta?.[x.ticker]?.source||prev.arsSource||prev.source:'');
    if(!ars&&x.cat==='CEDEAR'&&u?.usd&&ratio>0&&ccl>0){ars=u.usd*ccl/ratio;arsSource='Paridad estimada: subyacente USD × CCL ÷ ratio'}
    const theoretical=Number(localQ?.theoretical)||((u?.usd&&ccl&&ratio)?u.usd*ccl/ratio:0);
    db.prices[x.ticker]={...prev,ars,arsSource,source:arsSource,usd:Number(u?.usd)||Number(prev.usd)||0,usdSource:u?.source||prev.usdSource||'',ratio,theoretical,updated:new Date().toISOString()};
  }
  save();render();
  const detail=$('brokerDetail');if(detail&&!detail.classList.contains('hide')){const heading=detail.querySelector('h3');if(heading)showBroker(heading.textContent)}
  if($('connStatus'))$('connStatus').textContent='Cotizaciones actualizadas · '+fmtDateTime(new Date())+' · cadena multi-fuente';
}
