async function fetchBonistasSchedule(t){
  const clean=String(t||'').trim().toUpperCase();
  if(!clean)return null;
  const candidates=[clean,clean.endsWith('C')||clean.endsWith('D')?clean:clean+'C',clean.endsWith('C')||clean.endsWith('D')?clean:clean+'D'];
  for(const tk of candidates){
    const page='https://bonistas.com/bono-cotizacion-rendimiento-precio-hoy/'+encodeURIComponent(tk);
    const proxies=['https://r.jina.ai/'+page,'https://api.allorigins.win/raw?url='+encodeURIComponent(page)];
    for(const url of proxies){
      try{
        const r=await fetch(url); if(!r.ok)continue; const txt=await r.text();
        const rows=[]; const re=/(20\d\d-\d\d-\d\d)\s*\|\s*([\d.,-]+)\s*\|\s*([\d.,-]+)\s*\|\s*([\d.,-]+)\s*\|\s*([\d.,-]+)/g; let m;
        while((m=re.exec(txt))){const num=v=>{let z=String(v).trim();if(z==='-'||!z)return 0; if(z.includes(',')&&z.includes('.'))z=z.replace(/\./g,'').replace(',','.');else if(z.includes(','))z=z.replace(',','.'); return Number(z)||0}; rows.push([m[1],num(m[4]),num(m[3])]);}
        if(rows.length){
          let cur='USD'; const low=txt.toLowerCase(); if(/en pesos|moneda\s*\|\s*ars|\bars\b/.test(low)&&!/d[oó]lar|usd/.test(low.slice(0,2500)))cur='ARS';
          const maturity=rows[rows.length-1][0]; const sch={currency:cur,maturity,coupon:'Flujos tomados de Bonistas.com',payments:rows,source:'Bonistas.com'};
          bondSchedules[clean]=sch; bondSchedules[tk]=sch; db.marketMeta=db.marketMeta||{}; db.marketMeta[clean]={...(db.marketMeta[clean]||{}),maturity,source:'BYMA + Bonistas.com',currency:cur}; localStorage.setItem(KEY,JSON.stringify(db)); return sch;
        }
      }catch(e){}
    }
  }
  return null;
}
